package com.smartai.inventory;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class DataSeeder {
 @Bean CommandLineRunner seed(ProductRepository products,SupplierRepository suppliers,CustomerRepository customers){return args->{
  if(suppliers.count()==0){String[][] ss={{"TechSource India","Amit Sharma","sales@techsource.in","3"},{"Fresh Farms Co.","Priya Mehta","orders@freshfarms.in","2"},{"Urban Threads","Rohit Verma","hello@urbanthreads.in","2"},{"Glow Essentials","Neha Jain","care@glowessentials.in","1"}};for(String[] a:ss){Supplier s=new Supplier();s.setName(a[0]);s.setContact(a[1]);s.setEmail(a[2]);s.setProducts(Integer.parseInt(a[3]));s.setStatus("Active");suppliers.save(s);}}
  if(products.count()==0){Object[][] ps={{"Wireless Mouse","EL-MOU-01","Electronics",799.0,5,20,"TechSource India"},{"Basmati Rice 5kg","GR-RIC-05","Grocery",650.0,8,25,"Fresh Farms Co."},{"Men's Cotton T-Shirt","CL-TSH-12","Clothing",499.0,42,30,"Urban Threads"},{"Smartphone 128GB","EL-PHN-12","Electronics",18999.0,3,15,"TechSource India"},{"Instant Noodles Pack","GR-NOD-01","Grocery",60.0,10,20,"Fresh Farms Co."},{"Bluetooth Speaker","EL-SPK-04","Electronics",2499.0,27,10,"TechSource India"},{"Face Moisturizer","PC-MOI-02","Personal Care",349.0,64,20,"Glow Essentials"},{"Desk Organizer","HM-ORG-09","Home & Living",299.0,18,15,"Urban Threads"}};for(Object[] a:ps){Product p=new Product();p.setName((String)a[0]);p.setSku((String)a[1]);p.setCategory((String)a[2]);p.setPrice((Double)a[3]);p.setStock((Integer)a[4]);p.setReorder((Integer)a[5]);p.setSupplier((String)a[6]);products.save(p);}}
  if(customers.count()==0){String[][] cs={{"Aarav Enterprises","aarav@example.com","Business"},{"Mehta Retail","mehta@example.com","Business"},{"Kavya Singh","kavya@example.com","Individual"}};for(String[] a:cs){Customer c=new Customer();c.setName(a[0]);c.setEmail(a[1]);c.setType(a[2]);c.setOrders(0);c.setSpent(0.0);customers.save(c);}}
 };}
}
